import React, { useState } from 'react';
import { useNavigate, Link } from 'react-router-dom';
import api from '../utils/api';
import { toast } from 'react-toastify';

const Register = () => {
  const [form, setForm] = useState({
    name: '',
    email: '',
    password: '',
    college: '',
    department: '',
    role: 'student'
  });
  const navigate = useNavigate();

  const handleSubmit = async (e) => {
    e.preventDefault();
    try {
      await api.post('/auth/register', form);
      toast.success('Registration successful! Please login.');
      navigate('/login');
    } catch (error) {
      toast.error(error.response?.data?.message || 'Registration failed');
    }
  };

  return (
    <div className="min-h-screen bg-gradient-to-br from-blue-50 to-gray-100 py-12 px-4">
      <div className="max-w-2xl mx-auto">
        <div className="bg-white rounded-lg shadow-lg p-8">
          <h1 className="text-3xl font-bold mb-2 text-center text-blue-600">Create Account</h1>
          <p className="text-center text-gray-600 mb-8">Join our college event management system</p>

          {/* Role Selection Cards */}
          <div className="grid grid-cols-2 gap-4 mb-8">
            <button
              type="button"
              onClick={() => setForm({ ...form, role: 'student' })}
              className={`p-4 rounded-lg border-2 transition ${
                form.role === 'student'
                  ? 'border-blue-600 bg-blue-50'
                  : 'border-gray-300 hover:border-blue-300'
              }`}
            >
              <div className="text-3xl mb-2">👨‍🎓</div>
              <p className="font-bold">Student</p>
              <p className="text-xs text-gray-600">Register & attend events</p>
            </button>
            <button
              type="button"
              onClick={() => setForm({ ...form, role: 'admin' })}
              className={`p-4 rounded-lg border-2 transition ${
                form.role === 'admin'
                  ? 'border-blue-600 bg-blue-50'
                  : 'border-gray-300 hover:border-blue-300'
              }`}
            >
              <div className="text-3xl mb-2">🔐</div>
              <p className="font-bold">Admin</p>
              <p className="text-xs text-gray-600">Manage events</p>
            </button>
          </div>

          {/* Role Information */}
          <div className="mb-8 p-4 bg-gray-50 rounded-lg">
            {form.role === 'student' ? (
              <div>
                <p className="font-bold text-gray-800 mb-2">👨‍🎓 Student Account</p>
                <ul className="text-sm text-gray-700 space-y-1">
                  <li>✓ View all college events</li>
                  <li>✓ Register for events</li>
                  <li>✓ Receive certificates</li>
                  <li>✓ Track event status</li>
                </ul>
              </div>
            ) : (
              <div>
                <p className="font-bold text-gray-800 mb-2">🔐 Admin Account</p>
                <ul className="text-sm text-gray-700 space-y-1">
                  <li>✓ Create & manage events</li>
                  <li>✓ View participant registrations</li>
                  <li>✓ Mark attendance</li>
                  <li>✓ Generate certificates</li>
                  <li>✓ Declare winners</li>
                </ul>
              </div>
            )}
          </div>

          <form onSubmit={handleSubmit} className="space-y-4">
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">Full Name</label>
              <input
                type="text"
                placeholder="Enter your full name"
                value={form.name}
                onChange={(e) => setForm({ ...form, name: e.target.value })}
                className="w-full p-3 border rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
                required
              />
            </div>

            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">Email</label>
              <input
                type="email"
                placeholder="Enter your email"
                value={form.email}
                onChange={(e) => setForm({ ...form, email: e.target.value })}
                className="w-full p-3 border rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
                required
              />
            </div>

            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">Password</label>
              <input
                type="password"
                placeholder="Enter a strong password"
                value={form.password}
                onChange={(e) => setForm({ ...form, password: e.target.value })}
                className="w-full p-3 border rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
                required
              />
            </div>

            <div className="grid grid-cols-2 gap-4">
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">College</label>
                <input
                  type="text"
                  placeholder="College name"
                  value={form.college}
                  onChange={(e) => setForm({ ...form, college: e.target.value })}
                  className="w-full p-3 border rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
                  required
                />
              </div>
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">Department</label>
                <input
                  type="text"
                  placeholder="e.g., CSE, ECE, ME"
                  value={form.department}
                  onChange={(e) => setForm({ ...form, department: e.target.value })}
                  className="w-full p-3 border rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
                  required
                />
              </div>
            </div>

            <button
              type="submit"
              className="w-full bg-blue-600 text-white p-3 rounded-lg font-bold hover:bg-blue-700 transition"
            >
              Create Account as {form.role === 'student' ? 'Student' : 'Admin'}
            </button>
          </form>

          <p className="text-center text-gray-600 mt-6">
            Already have an account?{' '}
            <Link to="/login" className="text-blue-600 font-bold hover:underline">
              Login here
            </Link>
          </p>
        </div>
      </div>
    </div>
  );
};

export default Register;
